/bin/bash -lc "cat > index.html <<'EOF'
<"'!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="description" content="Find a little more room for your ideas. Compare Marginalia'"'s free Starter, Pro, and Team note-taking plans.\">
  <title>Pricing — Marginalia</title>
  <style>
    :root { --paper: #f8f9f5; --white: #fff; --ink: #24382f; --muted: #65716a; --green: #315b47; --line: #dfe5dc; --soft: #edf2e9; }
    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    body { margin: 0; background: var(--paper); color: var(--ink); font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif; font-size: 14px; line-height: 1.6; -webkit-font-smoothing: antialiased; }
    a { color: inherit; text-decoration: none; }
    button { font: inherit; }
    button, a, summary { -webkit-tap-highlight-color: transparent; }
    :focus-visible { outline: 3px solid #8fae75; outline-offset: 5px; }
    .wrap { width: min(1104px, calc(100% - 64px)); margin-inline: auto; }
    .svg-defs { position: absolute; width: 0; height: 0; overflow: hidden; }
    .icon { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex-shrink: 0; }
    .skip { position: absolute; left: 20px; top: -80px; padding: 10px 18px; background: white; z-index: 10; }
    .skip:focus { top: 12px; }
    .header { border-bottom: 1px solid var(--line); }
    .nav { min-height: 88px; display: flex; align-items: center; justify-content: space-between; gap: 30px; }
    .brand { display: inline-flex; align-items: center; gap: 10px; font: 27px Georgia, serif; letter-spacing: -1px; }
    .brand .icon { width: 30px; height: 30px; stroke-width: 1.4; }
    .nav-links, .nav-actions { display: flex; align-items: center; gap: 32px; }
    .nav-links { margin-left: auto; margin-right: 44px; color: var(--muted); font-size: 13px; }
    .nav-links a:hover, .footer a:hover { color: var(--green); text-decoration: underline; text-underline-offset: 5px; }
    .nav-links .current { color: var(--ink); font-weight: 600; position: relative; }
    .current::after { content: \"\"; position: absolute; bottom: -33px; left: 0; right: 0; height: 2px; background: var(--green); }
    .nav-actions { gap: 24px; font-size: 13px; }
    .nav-cta { padding: 10px 17px; border: 1px solid var(--green); border-radius: 6px; font-weight: 600; transition: background .2s; }
    .nav-cta:hover { background: var(--soft); }
    .hero { text-align: center; padding: 59px 0 37px; }
    .eyebrow { margin: 0 0 17px; color: var(--green); font-size: 10px; font-weight: 650; letter-spacing: 2.2px; text-transform: uppercase; }
    h1, h2, h3, p { margin-top: 0; }
    h1 { margin-bottom: 18px; font: 56px/1.12 Georgia, \"Times New Roman\", serif; letter-spacing: -2px; font-weight: 400; }
    h1 em { color: var(--green); font-weight: 400; }
    .hero-copy { margin: 0 auto; color: var(--muted); font-size: 15px; line-height: 1.8; }
    .billing { margin-top: 29px; display: inline-flex; align-items: center; gap: 3px; padding: 4px; border: 1px solid var(--line); background: #eff1eb; border-radius: 8px; }
    .billing button { border: 1px solid transparent; color: var(--muted); background: transparent; border-radius: 5px; padding: 8px 17px; cursor: pointer; font-size: 12px; }
    .billing button[aria-pressed=\"true\"] { background: var(--white); border-color: #e1e5dd; color: var(--ink); box-shadow: 0 1px 3px #24382f08; }
    .saving { margin-left: 7px; color: var(--green); font-size: 10px; font-weight: 600; }
    .plans { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px; scroll-margin-top: 24px; }
    .plan { position: relative; padding: 28px; background: var(--white); border: 1px solid var(--line); border-radius: 10px; display: flex; flex-direction: column; }
    .plan.popular { border-color: #65826b; background: #eef3e9; }
    .plan-heading { display: flex; align-items: center; gap: 9px; margin-bottom: 8px; }
    .plan-heading .icon { width: 18px; height: 18px; color: var(--green); }
    .plan h2 { font-size: 17px; font-weight: 600; margin: 0; letter-spacing: -.3px; }
    .badge { margin-left: auto; color: var(--green); background: #dce8d3; border-radius: 4px; padding: 3px 7px; font-size: 9px; font-weight: 650; letter-spacing: .2px; white-space: nowrap; }
    .desc { font-size: 12px; color: var(--muted); margin-bottom: 22px; }
    .price { display: flex; align-items: baseline; gap: 6px; line-height: 1; margin-bottom: 9px; }
    .amount { font-size: 46px; letter-spacing: -2px; font-weight: 500; }
    .price .unit { color: var(--muted); font-size: 12px; }
    .billing-note { font-size: 11px; color: var(--muted); margin-bottom: 22px; min-height: 18px; }
    .button { display: flex; justify-content: center; align-items: center; gap: 10px; width: 100%; min-height: 43px; border-radius: 5px; border: 1px solid #cdd7ca; color: var(--ink); font-size: 12px; font-weight: 600; transition: background .2s, border-color .2s; }
    .button .icon { width: 15px; height: 15px; }
    .button:hover { border-color: var(--green); background: #f4f7f0; }
    .popular .button { background: var(--green); color: white; border-color: var(--green); }
    .popular .button:hover { background: #244534; }
    .plan-features { border-top: 1px solid var(--line); margin-top: 24px; padding-top: 20px; }
    .popular .plan-features { border-color: #d5dfce; }
    .feature-label { font-size: 10px; font-weight: 600; letter-spacing: .5px; margin-bottom: 12px; }
    .plan ul { padding: 0; margin: 0; list-style: none; }
    .plan li { display: flex; align-items: center; gap: 10px; padding: 6px 0; font-size: 12px; }
    .plan li .icon { width: 14px; height: 14px; color: var(--green); stroke-width: 1.8; }
    .plan li.unavailable { color: #7a827c; }
    .plan li.unavailable .icon { color: #a0a79f; }
    .plan-note { display: flex; align-items: center; justify-content: center; gap: 7px; color: var(--muted); font-size: 11px; margin: 22px 0 0; }
    .plan-note .icon { width: 13px; height: 13px; }
    .features { padding: 61px 0 55px; border-bottom: 1px solid var(--line); scroll-margin-top: 30px; }
    .section-title { text-align: center; font: 28px/1.3 Georgia, serif; letter-spacing: -.6px; margin-bottom: 31px; font-weight: 400; }
    .feature-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 47px; }
    .feature { display: flex; gap: 14px; align-items: flex-start; }
    .feature-icon { display: flex; justify-content: center; align-items: center; width: 37px; height: 37px; background: #eaf0e5; border: 1px solid #e1e8db; border-radius: 8px; flex-shrink: 0; color: var(--green); }
    .feature-icon .icon { width: 17px; height: 17px; }
    .feature h3 { font-size: 12px; margin: 0 0 5px; font-weight: 600; }
    .feature p { color: var(--muted); font-size: 12px; line-height: 1.8; margin: 0; }
    .faq { display: grid; grid-template-columns: 1fr 1.6fr; gap: 90px; padding: 57px 0 66px; }
    .faq h2 { font: 30px/1.2 Georgia, serif; letter-spacing: -.6px; margin-bottom: 14px; }
    .faq-intro p { color: var(--muted); font-size: 12px; max-width: 220px; }
    details { border-bottom: 1px solid var(--line); }
    details:first-child { border-top: 1px solid var(--line); }
    summary { cursor: pointer; list-style: none; display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 19px 0; font-size: 12px; font-weight: 600; }
    summary::-webkit-details-marker { display: none; }
    summary::after { content: \"+\"; font-size: 20px; font-weight: 400; color: var(--muted); line-height: 1; }
    details[open] summary::after { content: \"−\"; }
    details p { font-size: 12px; color: var(--muted); margin: -3px 25px 20px 0; line-height: 1.8; }
    .footer { border-top: 1px solid var(--line); }
    .footer-inner { padding: 25px 0; display: flex; align-items: center; justify-content: space-between; gap: 20px; }
    .footer .brand { font-size: 20px; gap: 7px; }
    .footer .brand .icon { width: 23px; height: 23px; }
    .footer p { margin: 0; font-size: 10px; color: var(--muted); }
    @media (min-width: 1500px) { .hero { padding-top: 75px; padding-bottom: 45px; } }
    @media (max-width: 950px) {
      .wrap { width: calc(100% - 40px); }
      .nav-links { margin-right: 10px; gap: 22px; }
      .nav-actions { gap: 18px; }
      .plan { padding: 23px 19px; }
      .plans { gap: 13px; }
      .badge { font-size: 8px; padding-inline: 5px; }
      .feature-grid { gap: 24px; }
      .faq { gap: 40px; }
    }
    @media (max-width: 700px) {
      .nav { min-height: 76px; gap: 15px; }
      .brand { font-size: 24px; gap: 7px; }
      .brand .icon { width: 26px; height: 26px; }
      .nav-links, .login { display: none; }
      .nav-cta { padding: 8px 12px; font-size: 11px; }
      .hero { padding: 43px 0 30px; }
      h1 { font-size: 43px; letter-spacing: -1.6px; }
      .hero-copy { font-size: 14px; max-width: 340px; }
      .hero-copy br { display: none; }
      .eyebrow { font-size: 9px; margin-bottom: 16px; }
      .billing { margin-top: 24px; }
      .plans { grid-template-columns: 1fr; gap: 18px; max-width: 440px; margin-inline: auto; }
      .plan { padding: 25px; }
      .badge { font-size: 10px; padding: 3px 8px; }
      .desc { margin-bottom: 20px; }
      .plan li, .button, .desc { font-size: 13px; }
      .features { padding: 43px 0 37px; }
      .section-title { font-size: 26px; max-width: 290px; margin-inline: auto; }
      .feature-grid { grid-template-columns: 1fr; gap: 25px; max-width: 360px; margin: auto; }
      .feature h3 { font-size: 13px; }
      .faq { grid-template-columns: 1fr; gap: 16px; padding: 39px 0 45px; }
      .faq h2 { font-size: 28px; }
      .faq h2 br { display: none; }
      .faq-intro p { max-width: none; }
      summary { font-size: 13px; }
      .footer-inner { flex-wrap: wrap; padding: 22px 0; gap: 12px; }
      .footer p { font-size: 10px; }
    }
    @media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } * { transition: none "'!important; } }
  </style>
</head>
