  <svg class="svg-defs" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
    <defs>
      <symbol id="book" viewBox="0 0 24 24"><path d="M12 6C9 3.8 5.8 3.7 2.5 4.5v14c3.3-.8 6.5-.7 9.5 1.5 3-2.2 6.2-2.3 9.5-1.5v-14c-3.3-.8-6.5-.7-9.5 1.5Z"/><path d="M12 6v14M6 8l3 1M6 12l3 1M16 9l2-1M16 13l2-1"/></symbol>
      <symbol id="check" viewBox="0 0 24 24"><path d="m5 12 4 4L19 6"/></symbol>
      <symbol id="minus" viewBox="0 0 24 24"><path d="M6 12h12"/></symbol>
      <symbol id="arrow" viewBox="0 0 24 24"><path d="M5 12h14m-5-5 5 5-5 5"/></symbol>
      <symbol id="leaf" viewBox="0 0 24 24"><path d="M6 18C1 8 9 4 20 4c0 11-5 17-12 12M4 21 15 10"/></symbol>
      <symbol id="spark" viewBox="0 0 24 24"><path d="m12 3 2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6Z"/></symbol>
      <symbol id="team" viewBox="0 0 24 24"><circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/></symbol>
      <symbol id="bolt" viewBox="0 0 24 24"><path d="m13 2-9 12h7l-1 8 10-13h-8Z"/></symbol>
      <symbol id="lock" viewBox="0 0 24 24"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/></symbol>
      <symbol id="cloud" viewBox="0 0 24 24"><path d="M7 18a5 5 0 1 1 .6-10 6 6 0 0 1 11.6 1.4A4.3 4.3 0 0 1 18 18"/><path d="M12 21V12m-3 3 3-3 3 3"/></symbol>
    </defs>
  </svg>
  <a class="skip" href="#main">Skip to content</a>
  <header class="header">
    <nav class="nav wrap" aria-label="Main navigation">
      <a class="brand" href="#" aria-label="Marginalia home"><svg class="icon" aria-hidden="true"><use href="#book"/></svg>Marginalia</a>
      <div class="nav-links"><a href="#features">Features</a><a class="current" href="#pricing" aria-current="page">Pricing</a><a href="#">Blog</a></div>
      <div class="nav-actions"><a class="login" href="#">Log in</a><a class="nav-cta" href="#pricing">Sign up free <span aria-hidden="true">↗</span></a></div>
    </nav>
  </header>
  <main id="main" class="wrap">
    <section class="hero" aria-labelledby="heading">
      <p class="eyebrow">A little room for big ideas</p>
      <h1 id="heading">Your next chapter,<br><em>at your own pace.</em></h1>
      <p class="hero-copy">A home for your notes, thoughts, and everything in between.<br>Choose the plan that gives your ideas room to grow.</p>
      <div class="billing" role="group" aria-label="Billing period">
        <button type="button" aria-pressed="true" data-period="monthly">Monthly</button>
        <button type="button" aria-pressed="false" data-period="yearly">Yearly <span class="saving">Save 20%</span></button>
      </div>
    </section>
    <section id="pricing" class="plans" aria-label="Pricing plans">
      <article class="plan">
        <div class="plan-heading"><svg class="icon" aria-hidden="true"><use href="#leaf"/></svg><h2>Starter</h2></div>
        <p class="desc">For the first page and the everyday note.</p>
        <div class="price"><span class="amount">$0</span><span class="unit">/ month</span></div>
        <p class="billing-note">Free forever. A good place to begin.</p>
        <a class="button" href="#">Get started free <svg class="icon" aria-hidden="true"><use href="#arrow"/></svg></a>
        <div class="plan-features">
          <p class="feature-label">A SPACE TO START</p>
          <ul>
            <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Up to 100 notes</li>
            <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Sync across 2 devices</li>
            <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Basic search</li>
            <li class="unavailable"><svg class="icon" aria-hidden="true"><use href="#minus"/></svg>Offline access <span class="sr-only">(not included)</span></li>
            <li class="unavailable"><svg class="icon" aria-hidden="true"><use href="#minus"/></svg>Shared notebooks <span class="sr-only">(not included)</span></li>
          </ul>
        </div>
      </article>
      <article class="plan popular">
        <div class="plan-heading"><svg class="icon" aria-hidden="true"><use href="#spark"/></svg><h2>Pro</h2><span class="badge">Most popular</span></div>
        <p class="desc">More space for a mind that never stops.</p>
        <div class="price" aria-live="polite" aria-atomic="true"><span class="amount" data-monthly="8" data-yearly="6.40">$8</span><span class="unit">/ month</span></div>
        <p class="billing-note" data-annual="76.80">Billed monthly. Cancel anytime.</p>
        <a class="button" href="#">Try Pro free for 14 days <svg class="icon" aria-hidden="true"><use href="#arrow"/></svg></a>
        <div class="plan-features">
          <p class="feature-label">ROOM TO GO FURTHER</p>
          <ul>
            <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Unlimited notes</li>
            <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Sync across unlimited devices</li>
            <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Full-text search inside PDFs</li>
            <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Offline access</li>
            <li class="unavailable"><svg class="icon" aria-hidden="true"><use href="#minus"/></svg>Shared notebooks <span class="sr-only">(not included)</span></li>
          </ul>
        </div>
      </article>
      <article class="plan">
        <div class="plan-heading"><svg class="icon" aria-hidden="true"><use href="#team"/></svg><h2>Team</h2></div>
        <p class="desc">A shared home for your team'"'s thinking.</p>
        <div class=\"price\" aria-live=\"polite\" aria-atomic=\"true\"><span class=\"amount\" data-monthly=\"14\" data-yearly=\"11.20\">"'$14</span><span class="unit">/ user / month</span></div>
        <p class="billing-note" data-annual="134.40">Billed monthly. Cancel anytime.</p>
        <a class="button" href="#">Get started with Team <svg class="icon" aria-hidden="true"><use href="#arrow"/></svg></a>
        <div class="plan-features">
          <p class="feature-label">BETTER IDEAS, TOGETHER</p>
          <ul>
            <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Everything in Pro</li>
            <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Shared notebooks</li>
            <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Admin controls</li>
            <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Priority support</li>
            <li><svg class="icon" aria-hidden="true"><use href="#check"/></svg>Single sign-on (SSO)</li>
          </ul>
        </div>
      </article>
    </section>
    <p class="plan-note"><svg class="icon" aria-hidden="true"><use href="#lock"/></svg>No credit card needed for your 14-day Pro trial.</p>
    <section id="features" class="features" aria-labelledby="features-heading">
      <h2 class="section-title" id="features-heading">Thoughtfully made. Whichever plan you choose.</h2>
      <div class="feature-grid">
        <div class="feature"><div class="feature-icon"><svg class="icon" aria-hidden="true"><use href="#bolt"/></svg></div><div><h3>Less searching. More finding.</h3><p>Find the thought you'"'re looking for with fast, intuitive search.</p></div></div>
        <div class=\"feature\"><div class=\"feature-icon\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#lock\"/></svg></div><div><h3>Your thoughts, kept safe.</h3><p>Your notes are encrypted, so your ideas stay in good hands.</p></div></div>
        <div class=\"feature\"><div class=\"feature-icon\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#cloud\"/></svg></div><div><h3>Pick up where you left off.</h3><p>Keep your notes in sync, wherever the day takes you.</p></div></div>
      </div>
    </section>
    <section class=\"faq\" aria-labelledby=\"faq-heading\">
      <div class=\"faq-intro\"><p class=\"eyebrow\">A few more things</p><h2 id=\"faq-heading\">Good questions.<br>Simple answers.</h2><p>The little details, before you turn the page.</p></div>
      <div class=\"questions\">
        <details open><summary>Can I cancel anytime?</summary><p>Yes. You can cancel your subscription at any time, no questions asked.</p></details>
        <details><summary>Is there a free trial for Pro?</summary><p>Yes, Pro comes with a 14-day free trial. No credit card required.</p></details>
        <details><summary>Do you offer student discounts?</summary><p>Yes. Students get 50% off Pro with a valid school email.</p></details>
      </div>
    </section>
  </main>
  <footer class=\"footer\"><div class=\"wrap footer-inner\"><a class=\"brand\" href=\"#\"><svg class=\"icon\" aria-hidden=\"true\"><use href=\"#book\"/></svg>Marginalia</a><p>© 2026 Marginalia Inc. All rights reserved.</p><p>A little space for what matters.</p></div></footer>
  <script>
    const billingButtons = document.querySelectorAll('[data-period]');
    billingButtons.forEach(button => {
      button.addEventListener('click', () => {
        const yearly = button.dataset.period === 'yearly';
        billingButtons.forEach(item => item.setAttribute('aria-pressed', String(item === button)));
        document.querySelectorAll('[data-monthly]').forEach(price => {
          price.textContent = '"'$'"' + price.dataset[yearly ? 'yearly' : 'monthly'];
        });
        document.querySelectorAll('[data-annual]').forEach(note => {
          const perUser = note.closest('.plan').querySelector('.unit').textContent.includes('user');
          note.textContent = yearly
            ? '"'$'"' + note.dataset.annual + (perUser ? ' per user, billed yearly.' : ' billed yearly.')
            : 'Billed monthly. Cancel anytime.';
        });
      });
    });
  </script>
</body>
</html>
EOF"

